def transform(grid):
    """Tile 8-cells with 2x2 squares and L triominoes; color by tile type/orientation."""
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    pieces = []
    # Full 2x2 square -> color 1.
    for r in range(h - 1):
        for c in range(w - 1):
            s = frozenset(((r,c),(r+1,c),(r,c+1),(r+1,c+1)))
            if s <= cells:
                pieces.append((s, 1))
    # L triominoes. Color is determined by the missing corner of its 2x2 box.
    color_for_missing = {(0,0):2, (1,0):3, (0,1):4, (1,1):5}
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
            for missing, color in color_for_missing.items():
                m = (r+missing[0], c+missing[1])
                s = frozenset(box - {m})
                if s <= cells:
                    pieces.append((s, color))
    by_cell = {p: [] for p in cells}
    for i, (s, color) in enumerate(pieces):
        for p in s:
            by_cell[p].append(i)
    # Exact-cover search; prefer the most constrained remaining cell.
    def solve(rem):
        if not rem:
            return []
        p = min(rem, key=lambda q: sum(pieces[i][0] <= rem for i in by_cell[q]))
        for i in by_cell[p]:
            shape, color = pieces[i]
            if shape <= rem:
                tail = solve(rem - shape)
                if tail is not None:
                    return [(shape, color)] + tail
        return None
    tiling = solve(cells)
    if tiling is None:
        raise ValueError('foreground cannot be tiled by squares and L triominoes')
    out = [[0 for _ in row] for row in grid]
    for shape, color in tiling:
        for r, c in shape:
            out[r][c] = color
    return out
